// Copies the browser-safe compiled packages into apps/admin/js/vendor so the
// admin can run the same business rules in the browser (DEMO driver).
// Bare '@ubc/*' imports are rewritten to relative paths (no import maps: they
// are not supported on older iOS Safari versions).
import { cpSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const vendor = join(root, 'apps/admin/js/vendor');
rmSync(vendor, { recursive: true, force: true });
mkdirSync(vendor, { recursive: true });

function copyDir(pkg, name, depth) {
  const src = join(root, 'packages', pkg, 'dist');
  const dst = join(vendor, name);
  mkdirSync(dst, { recursive: true });
  for (const f of readdirSync(src)) {
    if (!f.endsWith('.js')) continue;
    let code = readFileSync(join(src, f), 'utf8');
    code = code.replace(/from ['"]@ubc\/shared['"]/g, `from '${depth}shared/index.js'`).replace(/\/\/# sourceMappingURL=.*$/m, '');
    if (/from ['"]@ubc\//.test(code)) throw new Error(`Unresolved @ubc import in ${pkg}/${f}`);
    writeFileSync(join(dst, f), code);
  }
}
copyDir('shared', 'shared', '../');
copyDir('business-rules', 'business-rules', '../');
copyDir('demo-data', 'demo-data', '../');
const csv = readFileSync(join(root, 'packages/integrations/dist/suppliers/csv.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
writeFileSync(join(vendor, 'csv.js'), csv);
writeFileSync(join(vendor, 'README.txt'), 'Generated by scripts/build-admin.mjs from packages/*/dist. Do not edit.\n');
console.log('admin vendor bundle ready:', vendor);
